-- Richer track background: corners, direction, length and elevation notes, a fuller history and cool facts. Safe to re-run.
alter table public.track_venues add column if not exists direction text;
alter table public.track_venues add column if not exists corners integer check (corners is null or corners > 0);
alter table public.track_venues add column if not exists corners_layout text;
alter table public.track_venues add column if not exists length_note text;
alter table public.track_venues add column if not exists elevation_note text;
alter table public.track_venues add column if not exists facts text[];
notify pgrst, 'reload schema';

update public.track_venues set direction = 'clockwise', corners = 9, corners_layout = 'Grand Prix Circuit', length_note = '3.916 km (2.433 mi)', elevation_note = 'Paddock Hill Bend drops at gradients of about 8%.', history = 'Brands Hatch started as a grass track for motorcycles on farmland in Kent. It became a tarmac racing circuit in 1950, and its racing direction was reversed to clockwise in 1953 to 1954. The longer Grand Prix layout was first built in 1960 and reshaped several times since, most recently to its current length in 2003. It hosted 12 British Grands Prix between 1964 and 1986.', facts = array['Paddock Hill Bend is a right-hander with gradients of about 8%, and the straight leading into it makes it one of the few overtaking spots.','The Dingle Dell chicane was reprofiled over the winter of 2002 to 2003, and the new complex was named Sheene Curve after Barry Sheene died shortly afterwards.']::text[], source_url = 'https://en.wikipedia.org/wiki/Brands_Hatch' where name = 'Brands Hatch';
update public.track_venues set direction = null, corners = 14, corners_layout = 'Grand Prix Circuit without the chicane (16 with it)', length_note = '4.657 km (2.894 mi)', elevation_note = null, history = 'Ground was broken on the circuit in February 1989, and it opened in September 1991 as the Circuit de Catalunya. It has hosted the Spanish Grand Prix since that first year. A slow chicane replaced the final fast corners in 2007, and its layout has been revised several times since.', facts = array['The Barcelona in the name was added through a sponsorship deal with Barcelona City Council, even though the track is in Montmeló.','Campsa Corner (Turn 9) is a fast right-hander that is completely blind, so drivers cannot see the apex on approach.','Max Verstappen won his first Grand Prix here in 2016, becoming the youngest driver ever to win an F1 race.']::text[], source_url = 'https://en.wikipedia.org/wiki/Circuit_de_Barcelona-Catalunya' where name = 'Circuit de Barcelona-Catalunya';
update public.track_venues set direction = null, corners = 19, corners_layout = 'Grand Prix Circuit (2007 onwards)', length_note = '7.004 km (4.352 mi)', elevation_note = 'Eau Rouge and Raidillon climb at a gradient above 18%.', history = 'The circuit opened in August 1921, though the planned first race was cancelled because only one driver entered. Racing began in 1922, and the first 24 Hours of Francorchamps took place in 1924. In 1979 the track was cut from 14.100 km to 6.947 km over safety worries about the old public-road course. Formula One returned in 1983 and came back again in 2007 after a renovation. It also hosts the Spa 24 Hours and the 6 Hours of Spa.', facts = array['The Eau Rouge and Raidillon section has a maximum gradient in excess of 18%.','Eau rouge is French for red water and refers to the water on the riverbanks near the circuit.','Jacques Villeneuve and Ricardo Zonta reportedly bet on taking Eau Rouge flat out, and both crashed there in qualifying for the 1999 Belgian Grand Prix.']::text[], source_url = 'https://en.wikipedia.org/wiki/Circuit_de_Spa-Francorchamps' where name = 'Circuit de Spa-Francorchamps';
update public.track_venues set direction = null, corners = 4, corners_layout = 'NASCAR tri-oval', length_note = '4.023 km (2.500 mi)', elevation_note = 'Banking of 31 degrees in the turns, 18 degrees at the tri-oval and 3 degrees on the back straight.', history = 'NASCAR founder Bill France Sr. began planning the speedway in 1953 so the series could move off the Daytona Beach Road Course. Ground was broken in November 1957, and the track opened in February 1959. It was repaved in 1978 and 2010, and the Daytona Rising project added permanent seating in 2016. It hosts the Daytona 500 and the 24 Hours of Daytona.', facts = array['Digging soil for the banking left a hole that filled with water and became Lake Lloyd, which was stocked with fish and used for speedboat races.','Because the banking is so steep, the paving equipment had to be anchored to bulldozers at the top of the incline so it would not slide down.','Sega''s 1994 arcade game Daytona USA was based on the circuit.']::text[], source_url = 'https://en.wikipedia.org/wiki/Daytona_International_Speedway' where name = 'Daytona Intl Speedway';
update public.track_venues set direction = null, corners = 17, corners_layout = 'Grand Prix Circuit (2002 onwards)', length_note = '4.574 km (2.842 mi)', elevation_note = null, history = 'The track was built in 1932 as a triangular course of about 12 km near Hockenheim. It was cut to just over 7.5 km in 1938 and renamed Kurpfalzring, then repaired after wartime damage and renamed Hockenheimring. The Motodrom stadium section was added in 1965 after the A6 Autobahn cut the village off. Hermann Tilke redesigned it for 2002, shortening it to 4.574 km. The last German Grand Prix held here was in 2019.', facts = array['The first chicane is named after Jim Clark, who died in a Formula 2 accident at the track in 1968, and a memorial stands there.','The second chicane was renamed after Ayrton Senna following his death in 1994.','The old forest straights were removed in the 2002 redesign, and the abandoned section was replanted with trees.']::text[], source_url = 'https://en.wikipedia.org/wiki/Hockenheimring' where name = 'Hockenheimring';
update public.track_venues set direction = null, corners = null, corners_layout = 'Oval', length_note = '2.414 km (1.500 mi)', elevation_note = 'Banking of 18 to 20 degrees in the turns and 4 degrees on the straights.', history = 'Promoter Ralph Sanchez began planning a permanent home for the Grand Prix of Miami in 1991, and the city of Homestead, recovering from Hurricane Andrew, persuaded him to build there. Ground was broken in August 1993 and the track opened in November 1995. Its rectangular layout was reconfigured into an oval in 1997, and the turns were banked to 18 to 20 degrees in 2003. IndyCar''s Grand Prix of Miami ran here from 1996 to 2010.', facts = array['The infield lake is 90 ft (27 m) deep and is sometimes used for fishing tournaments.','The track was first named the Miami-Dade Homestead Motorsports Complex and became Homestead-Miami Speedway in 1999.','Its first race, a Busch Series event in 1995, drew a crowd of 65,000.']::text[], source_url = 'https://en.wikipedia.org/wiki/Homestead%E2%80%93Miami_Speedway' where name = 'Homestead-Miami Speedway';
update public.track_venues set direction = 'anticlockwise', corners = 4, corners_layout = 'Rectangular oval', length_note = '4.023 km (2.500 mi)', elevation_note = 'Turns banked at 9.2 degrees; the straights are flat.', history = 'Carl G. Fisher conceived the track in 1905 as a proving ground for the auto industry, and it opened in 1909. The Indianapolis 500 has run since 1911 and the Brickyard 400 since 1994. An infield road course was completed in 2000, when it hosted the US Grand Prix through 2007, and it was reconfigured in 2008 and 2014.', facts = array['Only a three-foot-wide strip of bricks at the start-finish line, the Yard of Bricks, remains after the rest was paved over in 1961.','The first event was a helium balloon race in June 1909, more than two months before the oval was finished.','It was the second purpose-built banked oval, after Brooklands.']::text[], source_url = 'https://en.wikipedia.org/wiki/Indianapolis_Motor_Speedway' where name = 'Indianapolis Motor Speedway';
update public.track_venues set direction = 'clockwise', corners = 16, corners_layout = 'Grand Prix Circuit (2015 onwards)', length_note = '4.529 km (2.814 mi)', elevation_note = null, history = 'The original circuit was designed and cleared by Harry Pierce and Dick Bremner in the mid-1950s and opened in November 1961 with the Kyalami 9 Hours. It was widened in 1968 and rebuilt in 1989 as part of a commercial development, which made it narrower and twistier. It hosted the South African Grand Prix from 1967 to 1985 and again in 1992 and 1993. The circuit was auctioned in 2014 and then upgraded, and it now hosts the Kyalami 9 Hours.', facts = array['Crowthorne Corner was named after the nearby Crowthorne Hotel.','Sunset Bend got its name because it often forced drivers to face the setting sun.','Jody Scheckter became the first and only South African driver to win his home Grand Prix, at Kyalami in 1975.']::text[], source_url = 'https://en.wikipedia.org/wiki/Kyalami' where name = 'Kyalami Grand Prix Circuit';
update public.track_venues set direction = null, corners = 38, corners_layout = 'Circuit des 24 Heures du Mans (current configuration)', length_note = '13.626 km (8.467 mi)', elevation_note = null, history = 'The circuit opened on 26 May 1923 and is largely made up of public roads. The 1932 layout bypassed the city and stayed almost unchanged after the 1955 disaster. A smaller Bugatti Circuit was added in 1965, and a 1972 revamp cost 300 million francs. The Tertre Rouge corner was reprofiled after a fatal crash in 2013, and the current layout has been used since 2018. It hosts the 24 Hours of Le Mans, the World Endurance Championship and the French motorcycle Grand Prix.', facts = array['The Mulsanne Straight, about 6 km long, saw Roger Dorchy''s Project 400 car clocked by radar at 407 km/h in 1988.','Two chicanes were added to the Mulsanne Straight before the 1990 race because the FIA would no longer sanction a circuit with a straight longer than 2 km.','Part of the track is the public road D338, and these public sections remain accessible most of the year.']::text[], source_url = 'https://en.wikipedia.org/wiki/Circuit_de_la_Sarthe' where name = 'Le Mans - Circuit International de la Sarthe';
update public.track_venues set direction = null, corners = 7, corners_layout = 'Classic layout (other layouts have 8, 9 and 10 turns)', length_note = 'About 2.4 km (1.5 mi)', elevation_note = null, history = 'Jim Vaill conceived the track in 1956 and built it with John Fitch and Cornell Aeronautical Laboratory. It opened on 27 April 1957, with its first race the next day. It was repaved in 2008, when two new corner complexes were added. It is described as the third-oldest continuously operating road racing venue in the United States.', facts = array['A 1959 court injunction banning Sunday racing still stands today, so racing happens on Fridays and Saturdays.','The classic layout has only one left turn, called The Left-Hander, followed by The Right-Hander.']::text[], source_url = 'https://en.wikipedia.org/wiki/Lime_Rock_Park' where name = 'Lime Rock Park';
update public.track_venues set direction = null, corners = 12, corners_layout = 'Grand Prix Circuit', length_note = '4.088 km (2.540 mi)', elevation_note = null, history = 'Three investors bought about 750 acres of farmland in Braselton, Georgia in 1969, and the track opened on 13 September 1970 after roughly six months of construction. The site was chosen after flooding cancelled a Can-Am race at the original venue. Don Panoz bought the circuit in 1996 and upgraded it to FIA standards, and it hosted the first Petit Le Mans in 1998. IMSA''s parent company took ownership in 2012, and the track was renamed Michelin Raceway Road Atlanta in 2019.', facts = array['The track hosted the SCCA Runoffs every year from 1970 to 1993.','A 10,000-seat terrace was built around the Turn 10 complex.','Panoz-era changes added a chicane at the end of the long back straight and removed a feature called the Dip.']::text[], source_url = 'https://en.wikipedia.org/wiki/Road_Atlanta' where name = 'Michelin Raceway Road Atlanta';
update public.track_venues set direction = null, corners = 13, corners_layout = 'Second road course (1990 layout)', length_note = '3.634 km (2.258 mi)', elevation_note = null, history = 'Les Griebling and a group of Mansfield-area businessmen opened the track in 1962 for weekend sports car racing, and the first sports car race followed in 1963. In 1982 Red Roof Inns founder Jim Trueman bought it and added permanent grandstands, garages and a scoreboard tower. A shorter second layout opened in 1990 by paving a straight through the old chicane section. Green Savoree Racing Promotions has owned it since 2011.', facts = array['Oak Tree Bend, a series of turns in the northeast corner, was removed after one year for being too slow.','The downhill straight that replaced it is called Thunder Valley.','The runoff area at Turn 4 is known as China Beach.']::text[], source_url = 'https://en.wikipedia.org/wiki/Mid-Ohio_Sports_Car_Course' where name = 'Mid-Ohio Sports Car Course';
update public.track_venues set direction = 'anticlockwise', corners = 23, corners_layout = 'Full circuit (1987 onwards)', length_note = '6.213 km (3.861 mi)', elevation_note = '174 m (571 ft) between the highest and lowest points, with grades as steep as 1 in 6.13.', history = 'Construction began in mid-1936 and the circuit opened on 17 March 1938, with the Australian Grand Prix as its first car race two days after a motorcycle meeting. It replaced earlier public-road venues around Bathurst. A three-turn sequence called The Chase was added in 1987 to meet an FIA limit on straight length. It is home to the Bathurst 1000 and the Bathurst 12 Hour.', facts = array['The circuit is a public road on non-race days, open to traffic in both directions with a strictly enforced 60 km/h limit.','Conrod Straight was once called Main Straight and was renamed after a con-rod failure ended a race in 1939.']::text[], source_url = 'https://en.wikipedia.org/wiki/Mount_Panorama_Circuit' where name = 'Mount Panorama Circuit';
update public.track_venues set direction = null, corners = 15, corners_layout = 'Grand Prix Circuit (1974 onwards)', length_note = '5.245 km (3.259 mi)', elevation_note = null, history = 'Racing in the area began in the 1920s on public roads starting from the village of Scarperia, including the Futa Pass that was part of the Mille Miglia. Public-road racing ended after the 1970 race. The current closed circuit was built in 1973 and opened in 1974, about 5 km east of the old road course. Ferrari has owned it since 1988 and uses it for Formula One testing.', facts = array['The 2020 Tuscan Grand Prix was the circuit''s first Formula One race and Ferrari''s 1000th Grand Prix.','Its stadium stands hold 50,000 spectators.']::text[], source_url = 'https://en.wikipedia.org/wiki/Mugello_Circuit' where name = 'Mugello Circuit';
update public.track_venues set direction = 'clockwise', corners = 154, corners_layout = 'Nordschleife (1983 onwards)', length_note = '20.832 km (12.944 mi)', elevation_note = 'Elevation changes by more than 300 m (1,000 ft) from lowest to highest point.', history = 'Construction began in September 1925 and the track was finished in spring 1927, with the first races in June of that year. Formula One raced on the full Nordschleife from 1951 to 1976, leaving the old track after Niki Lauda''s 1976 crash. A bypass shortened the loop in 1983, and the separate Grand Prix circuit opened in 1984. The Nordschleife stays open for public touring on most days between mid-March and mid-November, except during racing.', facts = array['Jackie Stewart nicknamed it the Green Hell after winning the 1968 German Grand Prix in heavy rain and fog.','The Karussell, a 210-degree banked hairpin, is officially the Caracciola-Karussell, named after pre-war driver Rudolf Caracciola.']::text[], source_url = 'https://en.wikipedia.org/wiki/N%C3%BCrburgring' where name = 'Nürburgring';
update public.track_venues set direction = null, corners = 14, corners_layout = 'Grand Prix course', length_note = '6.515 km (4.048 mi)', elevation_note = null, history = 'Racing began in 1950 on public roads in and around Elkhart Lake, run by the Chicago Region SCCA and the village. After a fatal accident at Watkins Glen in 1952, public-highway speed contests were banned in the US, pushing the sport onto private tracks. Clif Tufte founded the private permanent track in 1955. The original road course was added to the National Register of Historic Places in 2006.', facts = array['The track sits in the Town of Plymouth, not Elkhart Lake, despite carrying the Elkhart Lake name early on.','It keeps its original layout, which is rare among road circuits worldwide.']::text[], source_url = 'https://en.wikipedia.org/wiki/Road_America' where name = 'Road America';
update public.track_venues set direction = null, corners = 17, corners_layout = 'Grand Prix road course', length_note = 'About 6.02 km (3.74 mi)', elevation_note = 'Flat Florida terrain with very little elevation change.', history = 'The site was Hendricks Army Airfield, a World War II training base for B-17 pilots that operated from 1941 to 1946. Alec Ulmann saw its runways and service roads as a venue for a sports car endurance race, and the first one ran on New Year''s Eve 1950 on a 3.5 mile, 12-turn circuit. The layout has been reshaped many times. After a 1966 crash that killed spectators, the Green Park Chicane replaced the Webster Turn in 1967.', facts = array['Much of the surface is original wartime runway concrete, and cars often throw sparks crossing its large seams.','The Grand Prix course is roughly 3.04 miles of asphalt and 0.7 miles of concrete.','Turn 17 is wide enough for three cars to run side by side.']::text[], source_url = 'https://en.wikipedia.org/wiki/Sebring_International_Raceway' where name = 'Sebring International Raceway';
update public.track_venues set direction = null, corners = 18, corners_layout = 'Arena Grand Prix circuit (2011 onwards)', length_note = '5.891 km (3.660 mi)', elevation_note = null, history = 'The site was RAF Silverstone, a bomber station that operated from 1943 to 1946, and its three runways lie within the present track. After an informal race in 1947, the Royal Automobile Club leased the airfield in 1948 and held the first British Grand Prix there. The 1950 British Grand Prix was the opening round of the first World Championship of Drivers.', facts = array['The informal September 1947 race was nicknamed the Mutton Grand Prix after a car hit a sheep on the airfield.','The Hangar Straight is about 770 m long and is the main overtaking zone, ending at Stowe.']::text[], source_url = 'https://en.wikipedia.org/wiki/Silverstone_Circuit' where name = 'Silverstone Racing Circuit';
update public.track_venues set direction = null, corners = 18, corners_layout = 'Grand Prix circuit', length_note = '5.807 km (3.608 mi)', elevation_note = null, history = 'Soichiro Honda decided in the late 1950s to build a permanent circuit in Mie Prefecture. Dutch engineer John Hugenholtz designed it in 1962 as a Honda test track. The 1987 Japanese Grand Prix was the first Formula One race held there, and it later hosted several championship deciders, including in 1988, 1989, 1990 and 1991. It is operated by Honda Mobilityland, a Honda subsidiary.', facts = array['Its figure-eight layout has the 1.2 km back straight crossing over the front section on an overpass.','It is the only FIA Grade 1 track with a figure-eight layout.','The Degner curve is named after Ernst Degner, who crashed a Suzuki 50 there at the first All Japan Championship Road Race meeting in 1962.']::text[], source_url = 'https://en.wikipedia.org/wiki/Suzuka_Circuit' where name = 'Suzuka Circuit';
update public.track_venues set direction = null, corners = 17, corners_layout = 'Full course', length_note = '5.262 km (3.270 mi)', elevation_note = 'About 130 ft (40 m) of elevation change around the course.', history = 'The track opened on 3 August 1957, built by a group of men using a bulldozer. It closed in 1974 and sat idle until it reopened in March 2000 under a country club membership model. It now hosts sports car and motorcycle events.', facts = array['Roller Coaster (Turn 14) is a scaled-down mirror image of the Corkscrew at Laguna Seca.','Oak Tree (Turn 11) leads onto a back straight of about 4,000 ft (1,200 m).','Hog Pen (Turn 17) is faster than Oak Tree and feeds the roughly 3,000 ft (910 m) front straight.']::text[], source_url = 'https://en.wikipedia.org/wiki/Virginia_International_Raceway' where name = 'Virginia International Raceway';
update public.track_venues set direction = null, corners = 11, corners_layout = 'Grand Prix circuit with the Inner Loop chicane', length_note = '5.552 km (3.450 mi)', elevation_note = null, history = 'Racing began in 1948 on public roads through the village of Watkins Glen. After a spectator was killed in 1952, the event moved to a wooded hilltop southwest of town. The first permanent circuit opened in 1956 at 3.782 km. In 1971 the Boot section was added, which gave the track its present Grand Prix shape, and the Inner Loop chicane followed in 1992 after serious crashes. The circuit hosted the Formula One United States Grand Prix for 20 consecutive years, from 1961 to 1980.', facts = array['The 1973 Summer Jam concert at the track drew about 600,000 people.','A chicane was added to the Esses after Francois Cevert''s fatal 1973 crash.','NASCAR has never raced on the full Grand Prix layout.']::text[], source_url = 'https://en.wikipedia.org/wiki/Watkins_Glen_International' where name = 'Watkins Glen International Speedway';
update public.track_venues set direction = null, corners = 11, corners_layout = 'Full circuit', length_note = '3.602 km (2.238 mi)', elevation_note = '180 ft (55 m) of elevation change overall; the Corkscrew drops 59 ft (18 m).', history = 'Laguna Seca was built in 1957 for about 1.5 million dollars, raised from local businesses and individuals, on part of the Fort Ord Army area. It was built after the nearby Pebble Beach road races were abandoned as too dangerous, and its first race was on 9 November 1957. A 1988 infield addition lengthened the original 1.9 mile track so it met motorcycle Grand Prix minimum-length rules. It has hosted Can-Am, Trans-Am, CART, IndyCar and IMSA.', facts = array['The name is Spanish for dry lake, after the lakebed the course was built around.','Pope John Paul II celebrated mass at the track in 1987 before about 72,000 people.','In 1996 Alex Zanardi passed Bryan Herta on the inside of the Corkscrew on the last lap to win.']::text[], source_url = 'https://en.wikipedia.org/wiki/WeatherTech_Raceway_Laguna_Seca' where name = 'WeatherTech Raceway Laguna Seca';
update public.track_venues set direction = null, corners = 16, corners_layout = 'Grand Prix circuit (2021 layout)', length_note = '5.281 km (3.281 mi)', elevation_note = '10.7 m (35 ft) of elevation change.', history = 'Yas Marina Circuit is on Yas Island, a headland in Abu Dhabi cut off from the mainland by a canal. Hermann Tilke designed it. Construction began in May 2007 and the circuit opened in October 2009, a week before the first Abu Dhabi Grand Prix. A 2021 reconfiguration replaced turns 4, 5 and 6 with a single hairpin and turned turns 11 to 14 into a sweeping banked curve, aiming to improve overtaking. The lap went from 21 turns to 16.', facts = array['The pit exit passes under the main circuit through a tunnel.','The surface uses graywacke aggregate shipped from a quarry in Shropshire, England.','The track passes the marina and runs under the W Abu Dhabi hotel.']::text[], source_url = 'https://en.wikipedia.org/wiki/Yas_Marina_Circuit' where name = 'Yas Marina Circuit';
update public.track_venues set direction = null, corners = null, corners_layout = null, length_note = 'Almost exactly one mile', elevation_note = null, history = 'Eaglerock Speedway is a fictional short-track oval with two short straights and two banked corners. It was teased at the June Xbox Games Showcase and officially named in an August reveal video, and it was one of the 20 tracks planned for the launch of Forza Motorsport (2023).', facts = array['Its reveal video showed a 2020 Audi RS 3 driving on the oval.']::text[], source_url = 'https://gtplanet.net/forza-motorsport-2023-new-tracks-launch-20230913' where name = 'Eaglerock Speedway';
update public.track_venues set direction = 'point-to-point', corners = 144, corners_layout = 'Full circuit', length_note = '16.5 km (10.24 mi)', elevation_note = 'About 826 m (2,711 ft) of climb from the Lake Ashi shore to the summit.', history = 'Fujimi Kaido first appeared in the original Forza Motorsport (2005) as a point-to-point mountain course popular with drifters. It was skipped in Forza Motorsport 2, returned in Forza Motorsport 3 at roughly double its original size, and last appeared on the Xbox 360 in Forza Motorsport 4. It came back to Forza Motorsport (2023) in the May 2025 20th Anniversary update, rebuilt to modern standards. Turn 10 deliberately kept the layout, including the pit lane, as close as possible to the Xbox 360 version.', facts = array['Turn 10 calls it the tallest track in Forza Motorsport.','The rebuilt track has 14 torii gates, three large Shinto shrines and just under 20,000 trees.','Players can see the separate Hakone circuit from the Fujimi mountaintop.']::text[], source_url = 'https://forza.net/news/forza-motorsport-fujimi-kaido' where name = 'Fujimi Kaido';
update public.track_venues set direction = null, corners = 7, corners_layout = null, length_note = null, elevation_note = 'Some interesting elevation changes, with no figure given.', history = 'Grand Oak Raceway is an original road course revealed by Turn 10 in August 2023, and it was the 15th venue confirmed for Forza Motorsport (2023). It is described as wide and flowing, mixing very fast sections with technical corners.', facts = array['Creative Director Chris Esaki compared it to Virginia International Raceway.','Esaki said the track is designed to teach players about carrying speed through corners.']::text[], source_url = 'https://gtplanet.net/forza-motorsport-2023-new-tracks-launch-20230913' where name = 'Grand Oak Raceway';
update public.track_venues set direction = null, corners = 9, corners_layout = null, length_note = null, elevation_note = 'Varied elevation changes, with no figure given.', history = 'Hakone is an original high-speed Grand Prix circuit first shown in June 2022. It has varied elevation changes, a hairpin and a long sweeping S-curve. Turn 10 says it shares a world location with Fujimi Kaido but is a separate track.', facts = array['Forza''s own Fujimi Kaido article says the Hakone circuit can be seen from the Fujimi mountaintop.']::text[], source_url = 'https://gtplanet.net/forza-motorsport-2023-new-tracks-launch-20230913' where name = 'Hakone';
update public.track_venues set direction = null, corners = 12, corners_layout = null, length_note = null, elevation_note = 'Elevation changes, with no figure given.', history = 'Maple Valley Raceway is a long-running Forza Motorsport track set in the New England woods, with rapid straights, narrow turns and an autumn look that is key to its charm. It has appeared in every Forza Motorsport game except 5 and 6, and the shape has not meaningfully changed in the 2023 game.', facts = array['Creative Director Chris Esaki used Maple Valley''s weather and day and night effects to reintroduce the new game about a year before launch.']::text[], source_url = 'https://gamingbolt.com/forza-motorsport-reveals-updated-maple-valley-raceway' where name = 'Maple Valley';
update public.track_venues set direction = null, corners = null, corners_layout = null, length_note = 'Full circuit about 4.47 km (2.78 mi); the oval is 3.93 km (2.44 mi)', elevation_note = 'The oval is high-banked and the infield is flat.', history = 'Sunset Peninsula Raceway is a long-straight, banked-turn track suited to testing top speed. It combines a tri-oval Speedway layout with a longer infield road course. According to the fan-maintained Forza Wiki, the oval has appeared in several Forza Motorsport games, including Forza Motorsport (2023).', facts = array['Forza.net used the Full Circuit for a Featured Rivals event with the 1982 Zakspeed Roush Mustang IMSA GT.']::text[], source_url = 'https://forza.fandom.com/wiki/Sunset_Peninsula_Raceway' where name = 'Sunset Peninsula Raceway';

select name from public.track_venues where facts is null and history is null order by name;
